    #define CONCAT_IN_DESCENDING_OCL_ORDER_0(i, j, k) k
  #elif OCL_DIM_R_1 == 1
    #define CONCAT_IN_DESCENDING_OCL_ORDER_1(i, j, k) k
  
    #define CONCAT_IN_DESCENDING_OCL_ORDER_0(i, j, k) j
  #endif
#elif OCL_DIM_L_2 == 2
  #define CONCAT_IN_DESCENDING_OCL_ORDER_2(i, j, k) j

  #if   OCL_DIM_L_1 == 1
    #define CONCAT_IN_DESCENDING_OCL_ORDER_1(i, j, k) i
  
    #define CONCAT_IN_DESCENDING_OCL_ORDER_0(i, j, k) k
  #elif OCL_DIM_R_1 == 1
    #define CONCAT_IN_DESCENDING_OCL_ORDER_1(i, j, k) k
  
    #define CONCAT_IN_DESCENDING_OCL_ORDER_0(i, j, k) i
  #endif
#elif OCL_DIM_R_1 == 2
  #define CONCAT_IN_DESCENDING_OCL_ORDER_2(i, j, k) k

  #if   OCL_DIM_L_1 == 1
    #define CONCAT_IN_DESCENDING_OCL_ORDER_1(i, j, k) i
  
    #define CONCAT_IN_DESCENDING_OCL_ORDER_0(i, j, k) j
  #elif OCL_DIM_L_2 == 1
    #define CONCAT_IN_DESCENDING_OCL_ORDER_1(i, j, k) j
  
    #define CONCAT_IN_DESCENDING_OCL_ORDER_0(i, j, k) i
  #endif
#endif
#define CONCAT_IN_DESCENDING_OCL_ORDER(i, j, k) CONCAT_IN_DESCENDING_OCL_ORDER_2(i, j, k)CONCAT_IN_DESCENDING_OCL_ORDER_1(i, j, k)CONCAT_IN_DESCENDING_OCL_ORDER_0(i, j, k)

#if   OCL_DIM_L_1 == 2
  #define FLAT_INDEX_IN_DESCENDING_OCL_ORDER_2(i_id, j_id, k_id, i_size, j_size, k_size) i_id

  #if   OCL_DIM_L_2 == 1
    #define FLAT_INDEX_IN_DESCENDING_OCL_ORDER_1(i_id, j_id, k_id, i_size, j_size, k_size) (FLAT_INDEX_IN_DESCENDING_OCL_ORDER_2(i_id, j_id, k_id, i_size, j_size, k_size)) * (j_size) + (j_id)
  
    #define FLAT_INDEX_IN_DESCENDING_OCL_ORDER_0(i_id, j_id, k_id, i_size, j_size, k_size) (FLAT_INDEX_IN_DESCENDING_OCL_ORDER_1(i_id, j_id, k_id, i_size, j_size, k_size)) * (k_size) + (k_id)
  #elif OCL_DIM_R_1 == 1
    #define FLAT_INDEX_IN_DESCENDING_OCL_ORDER_1(i_id, j_id, k_id, i_size, j_size, k_size) (FLAT_INDEX_IN_DESCENDING_OCL_ORDER_2(i_id, j_id, k_id, i_size, j_size, k_size)) * (k_size) + (k_id)
  
    #define FLAT_INDEX_IN_DESCENDING_OCL_ORDER_0(i_id, j_id, k_id, i_size, j_size, k_size) (FLAT_INDEX_IN_DESCENDING_OCL_ORDER_1(i_id, j_id, k_id, i_size, j_size, k_size)) * (j_size) + (j_id)
  #endif
#elif OCL_DIM_L_2 == 2
  #define FLAT_INDEX_IN_DESCENDING_OCL_ORDER_2(i_id, j_id, k_id, i_size, j_size, k_size) j_id

  #if   OCL_DIM_L_1 == 1
    #define FLAT_INDEX_IN_DESCENDING_OCL_ORDER_1(i_id, j_id, k_id, i_size, j_size, k_size) (FLAT_INDEX_IN_DESCENDING_OCL_ORDER_2(i_id, j_id, k_id, i_size, j_size, k_size)) * (i_size) + (i_id)
  
    #define FLAT_INDEX_IN_DESCENDING_OCL_ORDER_0(i_id, j_id, k_id, i_size, j_size, k_size) (FLAT_INDEX_IN_DESCENDING_OCL_ORDER_1(i_id, j_id, k_id, i_size, j_size, k_size)) * (k_size) + (k_id)
  #elif OCL_DIM_R_1 == 1
    #define FLAT_INDEX_IN_DESCENDING_OCL_ORDER_1(i_id, j_id, k_id, i_size, j_size, k_size) (FLAT_INDEX_IN_DESCENDING_OCL_ORDER_2(i_id, j_id, k_id, i_size, j_size, k_size)) * (k_size) + (k_id)
  
    #define FLAT_INDEX_IN_DESCENDING_OCL_ORDER_0(i_id, j_id, k_id, i_size, j_size, k_size) (FLAT_INDEX_IN_DESCENDING_OCL_ORDER_1(i_id, j_id, k_id, i_size, j_size, k_size)) * (i_size) + (i_id)
  #endif
#elif OCL_DIM_R_1 == 2
  #define FLAT_INDEX_IN_DESCENDING_OCL_ORDER_2(i_id, j_id, k_id, i_size, j_size, k_size) k_id

  #if   OCL_DIM_L_1 == 1
    #define FLAT_INDEX_IN_DESCENDING_OCL_ORDER_1(i_id, j_id, k_id, i_size, j_size, k_size) (FLAT_INDEX_IN_DESCENDING_OCL_ORDER_2(i_id, j_id, k_id, i_size, j_size, k_size)) * (i_size) + (i_id)
  
    #define FLAT_INDEX_IN_DESCENDING_OCL_ORDER_0(i_id, j_id, k_id, i_size, j_size, k_size) (FLAT_INDEX_IN_DESCENDING_OCL_ORDER_1(i_id, j_id, k_id, i_size, j_size, k_size)) * (j_size) + (j_id)
  #elif OCL_DIM_L_2 == 1
    #define FLAT_INDEX_IN_DESCENDING_OCL_ORDER_1(i_id, j_id, k_id, i_size, j_size, k_size) (FLAT_INDEX_IN_DESCENDING_OCL_ORDER_2(i_id, j_id, k_id, i_size, j_size, k_size)) * (j_size) + (j_id)
  
    #define FLAT_INDEX_IN_DESCENDING_OCL_ORDER_0(i_id, j_id, k_id, i_size, j_size, k_size) (FLAT_INDEX_IN_DESCENDING_OCL_ORDER_1(i_id, j_id, k_id, i_size, j_size, k_size)) * (i_size) + (i_id)
  #endif
#endif
#define FLAT_INDEX_IN_DESCENDING_OCL_ORDER(i_id, j_id, k_id, i_size, j_size, k_size) FLAT_INDEX_IN_DESCENDING_OCL_ORDER_0(i_id, j_id, k_id, i_size, j_size, k_size)

#if   OCL_DIM_L_1 == 2
