// cache block offsets
#define K1_G_CB_OFFSET_L_1 0 // == (K1_G_CB_SIZE_L_1 * (0 + i_g_cb_L_1 * 1))
#define K1_L_CB_OFFSET_L_1 (K1_L_CB_SIZE_L_1 * (K1_G_FU_ID_L_1 + i_l_cb_l_1 * K1_G_NUM_FU_L_1))
