#define K1_G_CB_RES_DEST(i, j) K1_RES_L_BUFFER(K1_P_CB_OFFSET_L_1 + (i), K1_P_CB_OFFSET_L_2 + (j), K1_L_FU_ID_R_1, K1_P_FU_ID_R_1)
#elif G_CB_RES_DEST_LEVEL == GLOBAL
#define K1_G_CB_RES_DEST(i, j) K1_RES_G_BUFFER(K1_P_CB_OFFSET_L_1 + (K1_L_CB_OFFSET_L_1 + (i)), K1_P_CB_OFFSET_L_2 + (K1_L_CB_OFFSET_L_2 + (j)), K1_G_FU_ID_R_1, K1_L_FU_ID_R_1, K1_P_FU_ID_R_1)
#endif

// check if seperate memory for reduction is needed
// will only be checked for local level, because of constraints for OpenCL
#if L_CB_RES_DEST_LEVEL < LOCAL
#define K1_L_REDUCTION_MEM_NAME() l_reduction_mem
#define K1_L_REDUCTION_MEM(i, j, k) K1_L_REDUCTION_MEM_NAME()CONCAT_IN_DESCENDING_OCL_ORDER([i], [j], [k])
#endif

// buffer abstraction for kernel_res buffer
#if K1_G_NUM_FU_R_1 == 1
// if result is final result, use requested ordering of L-dimensions
#define K1_KERNEL_RES_BUFFER(i, j, k) int_res[(i) * K1_G_CB_SIZE_L_2 + (j)]
#else
// else order in descending OpenCL dimension order
#define K1_KERNEL_RES_BUFFER(i, j, k) int_res[FLAT_INDEX_IN_DESCENDING_OCL_ORDER(i, j, k, K1_G_CB_SIZE_L_1, K1_G_CB_SIZE_L_2, K1_G_NUM_FU_R_1)]
#endif

#define K1_G_KERNEL_RES(i, j) K1_KERNEL_RES_BUFFER(K1_G_CB_OFFSET_L_1 + (i), K1_G_CB_OFFSET_L_2 + (j), K1_G_FU_ID_R_1)
#define K1_L_KERNEL_RES(i, j) K1_G_KERNEL_RES(K1_L_CB_OFFSET_L_1 + (i), K1_L_CB_OFFSET_L_2 + (j))
#define K1_P_KERNEL_RES(i, j) K1_L_KERNEL_RES(K1_P_CB_OFFSET_L_1 + (i), K1_P_CB_OFFSET_L_2 + (j))


// buffer abstraction for res_orig buffer
#define K1_KERNEL_RES_ORIG_BUFFER(i, j) S_orig[(i) * K1_G_CB_SIZE_L_2 + (j)]
#define K1_G_KERNEL_RES_ORIG(i, j) K1_KERNEL_RES_ORIG_BUFFER(K1_G_CB_OFFSET_L_1 + (i), K1_G_CB_OFFSET_L_2 + (j))
#define K1_L_KERNEL_RES_ORIG(i, j) K1_G_KERNEL_RES_ORIG(K1_L_CB_OFFSET_L_1 + (i), K1_L_CB_OFFSET_L_2 + (j))
#define K1_P_KERNEL_RES_ORIG(i, j) K1_L_KERNEL_RES_ORIG(K1_P_CB_OFFSET_L_1 + (i), K1_P_CB_OFFSET_L_2 + (j))
// =============== end of macro definitions per buffer ========================

// =============== scalar function ============================================
__device__ inline TYPE_TS f(const TYPE_T Z_val, const TYPE_T W_val) {
  return Z_val * W_val;
}
// =============== end of scalar function =====================================

// =============== result function ============================================
__device__ inline TYPE_TS g(const TYPE_T res) {
  return res;
}
// =============== end of result function =====================================

// =============== kernel 1 ===================================================
__global__ void matmul_1(TYPE_T const * const __restrict__ Z, TYPE_T const * const __restrict__ W, TYPE_TS * const __restrict__ res_g, TYPE_TS * const __restrict__ int_res, TYPE_TS * const __restrict__ S_orig) {
  // map md_hom dimensions to CUDA dimensions
  const size_t i_wg_l_1 = GET_GROUP_ID_L_1;
  const size_t i_wi_l_1 = GET_LOCAL_ID_L_1;
  
  const size_t i_wg_l_2 = GET_GROUP_ID_L_2;
  const size_t i_wi_l_2 = GET_LOCAL_ID_L_2;
  
  const size_t i_wg_r_1 = GET_GROUP_ID_R_1;
  const size_t i_wi_r_1 = GET_LOCAL_ID_R_1;
  
  // declare variables for caching inputs
  #if CACHE_L_CB != 0
  __shared__ TYPE_T cb_l_Z[BUFFER_Z_L_SIZE_1][BUFFER_Z_L_SIZE_0];
  __shared__ TYPE_T cb_l_W[BUFFER_W_L_SIZE_2][BUFFER_W_L_SIZE_1][BUFFER_W_L_SIZE_0];
  #endif
  #if CACHE_P_CB != 0
   TYPE_T cb_p_Z[BUFFER_Z_P_SIZE_1][BUFFER_Z_P_SIZE_0];
   TYPE_T cb_p_W[BUFFER_W_P_SIZE_2][BUFFER_W_P_SIZE_1][BUFFER_W_P_SIZE_0];
  #endif

  // declare variables for result memory
  // ------ LOCAL ------
  #ifdef K1_L_LEVEL_HAS_RESULTS
  __shared__ TYPE_TS K1_RES_L_BUFFER_DEF;
  #endif
  // ------ PRIVATE ------
  #ifdef K1_P_LEVEL_HAS_RESULTS
   TYPE_TS K1_RES_P_BUFFER_DEF;
  #endif
  
  // declare variables for reduction memory (if needed)
  #if L_CB_RES_DEST_LEVEL < LOCAL && (K1_L_NUM_FU_R_1 > 1)
  __shared__ TYPE_TS K1_L_REDUCTION_MEM_NAME()CONCAT_IN_DESCENDING_OCL_ORDER([K1_L_CB_SIZE_L_1], [K1_L_CB_SIZE_L_2], [K1_L_NUM_FU_R_1]);
  #endif

  // reset memory where reduction takes place for WIs that do not
  // calculate intermediate results, so that reduction can always
  // be done with all WIs
  #if K1_L_NUM_FU_R_1 > 1
  #if K1_L_NUM_CB_R_1 == 0 && (K1_L_NUM_EXTRA_CB_R_1 + (K1_L_NUM_EXTRA_ELEMS_R_1 > 0)) < K1_G_NUM_FU_R_1
  if (K1_G_FU_ID_R_1 < (K1_L_NUM_EXTRA_CB_R_1 + (K1_L_NUM_EXTRA_ELEMS_R_1 > 0)))
  #endif
  {
    #if K1_L_NUM_CB_R_1 > 0
    // all active WGs process whole local cache blocks
    #if K1_P_NUM_CB_R_1 > 0
    const size_t num_active_wi_r_1 = K1_L_NUM_FU_R_1;
    #else
    const size_t num_active_wi_r_1 = K1_P_NUM_EXTRA_CB_R_1 + (K1_P_NUM_EXTRA_ELEMS_R_1 > 0);
    #endif
    #else
    // not all active WGs process whole cache blocks
    size_t num_active_wi_r_1;
    if (K1_G_FU_ID_R_1 < K1_L_NUM_EXTRA_CB_R_1) {
      #if K1_P_NUM_CB_R_1 > 0
      num_active_wi_r_1 = K1_L_NUM_FU_R_1;
      #else
      num_active_wi_r_1 = K1_P_NUM_EXTRA_CB_R_1 + (K1_P_NUM_EXTRA_ELEMS_R_1 > 0);
      #endif
    } else {
      #if K1_P_NUM_CB_IN_INCOMPLETE_L_CB_IN_COMPLETE_G_CB_R_1 > 0
      num_active_wi_r_1 = K1_L_NUM_FU_R_1;
      #else
      num_active_wi_r_1 = K1_P_NUM_EXTRA_CB_IN_INCOMPLETE_L_CB_IN_COMPLETE_G_CB_R_1 + (K1_P_NUM_EXTRA_ELEMS_IN_INCOMPLETE_L_CB_IN_COMPLETE_G_CB_R_1 > 0);
      #endif
    }
    #endif
    
    if (K1_L_FU_ID_R_1 >= num_active_wi_r_1) {
      #if K1_L_NUM_CB_L_1 > 0
      for (size_t i_l_cb_l_1 = 0; i_l_cb_l_1 < K1_L_NUM_CB_L_1; ++i_l_cb_l_1) {
        #if K1_L_NUM_CB_L_2 > 0
        for (size_t i_l_cb_l_2 = 0; i_l_cb_l_2 < K1_L_NUM_CB_L_2; ++i_l_cb_l_2) {
          #if K1_P_NUM_CB_L_1 > 0
          for (size_t i_p_cb_l_1 = 0; i_p_cb_l_1 < K1_P_NUM_CB_L_1; ++i_p_cb_l_1) {
            #if K1_P_NUM_CB_L_2 > 0
            for (size_t i_p_cb_l_2 = 0; i_p_cb_l_2 < K1_P_NUM_CB_L_2; ++i_p_cb_l_2) {
              for (size_t i_p_elem_l_1 = 0; i_p_elem_l_1 < K1_P_CB_SIZE_L_1; ++i_p_elem_l_1) {
                for (size_t i_p_elem_l_2 = 0; i_p_elem_l_2 < K1_P_CB_SIZE_L_2; ++i_p_elem_l_2) {
                  K1_L_CB_RES_DEST(i_p_elem_l_1, i_p_elem_l_2) = 0;
                
                }
              }
            } // end of "i_p_cb_l_2"-loop
            #endif
            // post process whole extra cache blocks in dimension L_2
            #if K1_P_NUM_EXTRA_CB_L_2 > 0
            if (K1_L_FU_ID_L_2 < K1_P_NUM_EXTRA_CB_L_2) {  
              const size_t i_p_cb_l_2 = K1_P_NUM_CB_L_2;
              for (size_t i_p_elem_l_1 = 0; i_p_elem_l_1 < K1_P_CB_SIZE_L_1; ++i_p_elem_l_1) {
                for (size_t i_p_elem_l_2 = 0; i_p_elem_l_2 < K1_P_CB_SIZE_L_2; ++i_p_elem_l_2) {
                  K1_L_CB_RES_DEST(i_p_elem_l_1, i_p_elem_l_2) = 0;
                
                }
              }
            } // end of post processing whole extra cache blocks in dimension L_2
            #endif
            // post process single extra incomplete cache block in dimension L_2
            #if K1_P_NUM_EXTRA_ELEMS_L_2 > 0
            if (K1_L_FU_ID_L_2 == K1_P_NUM_EXTRA_CB_L_2 % K1_L_NUM_FU_L_2) {  
              const size_t i_p_cb_l_2 = K1_P_NUM_CB_L_2;
              for (size_t i_p_elem_l_1 = 0; i_p_elem_l_1 < K1_P_CB_SIZE_L_1; ++i_p_elem_l_1) {
                for (size_t i_p_elem_l_2 = 0; i_p_elem_l_2 < K1_P_CB_REDUCED_SIZE_IN_COMPLETE_L_CB_L_2; ++i_p_elem_l_2) {
                  K1_L_CB_RES_DEST(i_p_elem_l_1, i_p_elem_l_2) = 0;
                
                }
              }
            }// end of post process single extra incomplete cache block in dimension L_2
            #endif
          } // end of "i_p_cb_l_1"-loop
          #endif
          // post process whole extra cache blocks in dimension L_1
          #if K1_P_NUM_EXTRA_CB_L_1 > 0
          if (K1_L_FU_ID_L_1 < K1_P_NUM_EXTRA_CB_L_1) {  
            const size_t i_p_cb_l_1 = K1_P_NUM_CB_L_1;
            #if K1_P_NUM_CB_L_2 > 0
            for (size_t i_p_cb_l_2 = 0; i_p_cb_l_2 < K1_P_NUM_CB_L_2; ++i_p_cb_l_2) {
              for (size_t i_p_elem_l_1 = 0; i_p_elem_l_1 < K1_P_CB_SIZE_L_1; ++i_p_elem_l_1) {
                for (size_t i_p_elem_l_2 = 0; i_p_elem_l_2 < K1_P_CB_SIZE_L_2; ++i_p_elem_l_2) {
                  K1_L_CB_RES_DEST(i_p_elem_l_1, i_p_elem_l_2) = 0;
                
                }
              }
            } // end of "i_p_cb_l_2"-loop
            #endif
            // post process whole extra cache blocks in dimension L_2
            #if K1_P_NUM_EXTRA_CB_L_2 > 0
            if (K1_L_FU_ID_L_2 < K1_P_NUM_EXTRA_CB_L_2) {  
              const size_t i_p_cb_l_2 = K1_P_NUM_CB_L_2;
              for (size_t i_p_elem_l_1 = 0; i_p_elem_l_1 < K1_P_CB_SIZE_L_1; ++i_p_elem_l_1) {
                for (size_t i_p_elem_l_2 = 0; i_p_elem_l_2 < K1_P_CB_SIZE_L_2; ++i_p_elem_l_2) {
                  K1_L_CB_RES_DEST(i_p_elem_l_1, i_p_elem_l_2) = 0;
                
                }
              }
            } // end of post processing whole extra cache blocks in dimension L_2
            #endif
            // post process single extra incomplete cache block in dimension L_2
            #if K1_P_NUM_EXTRA_ELEMS_L_2 > 0
            if (K1_L_FU_ID_L_2 == K1_P_NUM_EXTRA_CB_L_2 % K1_L_NUM_FU_L_2) {  
              const size_t i_p_cb_l_2 = K1_P_NUM_CB_L_2;
              for (size_t i_p_elem_l_1 = 0; i_p_elem_l_1 < K1_P_CB_SIZE_L_1; ++i_p_elem_l_1) {
                for (size_t i_p_elem_l_2 = 0; i_p_elem_l_2 < K1_P_CB_REDUCED_SIZE_IN_COMPLETE_L_CB_L_2; ++i_p_elem_l_2) {
                  K1_L_CB_RES_DEST(i_p_elem_l_1, i_p_elem_l_2) = 0;
                
                }
              }
            }// end of post process single extra incomplete cache block in dimension L_2
            #endif
          } // end of post processing whole extra cache blocks in dimension L_1
          #endif
          // post process single extra incomplete cache block in dimension L_1
          #if K1_P_NUM_EXTRA_ELEMS_L_1 > 0
          if (K1_L_FU_ID_L_1 == K1_P_NUM_EXTRA_CB_L_1 % K1_L_NUM_FU_L_1) {  
            const size_t i_p_cb_l_1 = K1_P_NUM_CB_L_1;
            #if K1_P_NUM_CB_L_2 > 0
            for (size_t i_p_cb_l_2 = 0; i_p_cb_l_2 < K1_P_NUM_CB_L_2; ++i_p_cb_l_2) {
              for (size_t i_p_elem_l_1 = 0; i_p_elem_l_1 < K1_P_CB_REDUCED_SIZE_IN_COMPLETE_L_CB_L_1; ++i_p_elem_l_1) {
                for (size_t i_p_elem_l_2 = 0; i_p_elem_l_2 < K1_P_CB_SIZE_L_2; ++i_p_elem_l_2) {
                  K1_L_CB_RES_DEST(i_p_elem_l_1, i_p_elem_l_2) = 0;
                
                }
              }
            } // end of "i_p_cb_l_2"-loop
            #endif
            // post process whole extra cache blocks in dimension L_2
            #if K1_P_NUM_EXTRA_CB_L_2 > 0
            if (K1_L_FU_ID_L_2 < K1_P_NUM_EXTRA_CB_L_2) {  
              const size_t i_p_cb_l_2 = K1_P_NUM_CB_L_2;
              for (size_t i_p_elem_l_1 = 0; i_p_elem_l_1 < K1_P_CB_REDUCED_SIZE_IN_COMPLETE_L_CB_L_1; ++i_p_elem_l_1) {
                for (size_t i_p_elem_l_2 = 0; i_p_elem_l_2 < K1_P_CB_SIZE_L_2; ++i_p_elem_l_2) {
                  K1_L_CB_RES_DEST(i_p_elem_l_1, i_p_elem_l_2) = 0;
                
                }
              }
            } // end of post processing whole extra cache blocks in dimension L_2
            #endif
            // post process single extra incomplete cache block in dimension L_2
            #if K1_P_NUM_EXTRA_ELEMS_L_2 > 0
            if (K1_L_FU_ID_L_2 == K1_P_NUM_EXTRA_CB_L_2 % K1_L_NUM_FU_L_2) {  
              const size_t i_p_cb_l_2 = K1_P_NUM_CB_L_2;
              for (size_t i_p_elem_l_1 = 0; i_p_elem_l_1 < K1_P_CB_REDUCED_SIZE_IN_COMPLETE_L_CB_L_1; ++i_p_elem_l_1) {
                for (size_t i_p_elem_l_2 = 0; i_p_elem_l_2 < K1_P_CB_REDUCED_SIZE_IN_COMPLETE_L_CB_L_2; ++i_p_elem_l_2) {
                  K1_L_CB_RES_DEST(i_p_elem_l_1, i_p_elem_l_2) = 0;
                
                }
              }
            }// end of post process single extra incomplete cache block in dimension L_2
            #endif
          }// end of post process single extra incomplete cache block in dimension L_1
          #endif
        } // end of "i_l_cb_l_2"-loop
        #endif
        // post process whole extra cache blocks in dimension L_2
        #if K1_L_NUM_EXTRA_CB_L_2 > 0
        if (K1_G_FU_ID_L_2 < K1_L_NUM_EXTRA_CB_L_2) {  
          const size_t i_l_cb_l_2 = K1_L_NUM_CB_L_2;
          #if K1_P_NUM_CB_L_1 > 0
          for (size_t i_p_cb_l_1 = 0; i_p_cb_l_1 < K1_P_NUM_CB_L_1; ++i_p_cb_l_1) {
            #if K1_P_NUM_CB_L_2 > 0
            for (size_t i_p_cb_l_2 = 0; i_p_cb_l_2 < K1_P_NUM_CB_L_2; ++i_p_cb_l_2) {
              for (size_t i_p_elem_l_1 = 0; i_p_elem_l_1 < K1_P_CB_SIZE_L_1; ++i_p_elem_l_1) {
                for (size_t i_p_elem_l_2 = 0; i_p_elem_l_2 < K1_P_CB_SIZE_L_2; ++i_p_elem_l_2) {
                  K1_L_CB_RES_DEST(i_p_elem_l_1, i_p_elem_l_2) = 0;
                
                }
              }
            } // end of "i_p_cb_l_2"-loop
            #endif
            // post process whole extra cache blocks in dimension L_2
            #if K1_P_NUM_EXTRA_CB_L_2 > 0
            if (K1_L_FU_ID_L_2 < K1_P_NUM_EXTRA_CB_L_2) {  
              const size_t i_p_cb_l_2 = K1_P_NUM_CB_L_2;
              for (size_t i_p_elem_l_1 = 0; i_p_elem_l_1 < K1_P_CB_SIZE_L_1; ++i_p_elem_l_1) {
                for (size_t i_p_elem_l_2 = 0; i_p_elem_l_2 < K1_P_CB_SIZE_L_2; ++i_p_elem_l_2) {
                  K1_L_CB_RES_DEST(i_p_elem_l_1, i_p_elem_l_2) = 0;
                
                }
              }
            } // end of post processing whole extra cache blocks in dimension L_2
            #endif
            // post process single extra incomplete cache block in dimension L_2
            #if K1_P_NUM_EXTRA_ELEMS_L_2 > 0
            if (K1_L_FU_ID_L_2 == K1_P_NUM_EXTRA_CB_L_2 % K1_L_NUM_FU_L_2) {  
              const size_t i_p_cb_l_2 = K1_P_NUM_CB_L_2;
              for (size_t i_p_elem_l_1 = 0; i_p_elem_l_1 < K1_P_CB_SIZE_L_1; ++i_p_elem_l_1) {
                for (size_t i_p_elem_l_2 = 0; i_p_elem_l_2 < K1_P_CB_REDUCED_SIZE_IN_COMPLETE_L_CB_L_2; ++i_p_elem_l_2) {
                  K1_L_CB_RES_DEST(i_p_elem_l_1, i_p_elem_l_2) = 0;
                
                }
              }
            }// end of post process single extra incomplete cache block in dimension L_2
            #endif
          } // end of "i_p_cb_l_1"-loop
          #endif
          // post process whole extra cache blocks in dimension L_1
          #if K1_P_NUM_EXTRA_CB_L_1 > 0
          if (K1_L_FU_ID_L_1 < K1_P_NUM_EXTRA_CB_L_1) {  
            const size_t i_p_cb_l_1 = K1_P_NUM_CB_L_1;
            #if K1_P_NUM_CB_L_2 > 0
            for (size_t i_p_cb_l_2 = 0; i_p_cb_l_2 < K1_P_NUM_CB_L_2; ++i_p_cb_l_2) {
              for (size_t i_p_elem_l_1 = 0; i_p_elem_l_1 < K1_P_CB_SIZE_L_1; ++i_p_elem_l_1) {
                for (size_t i_p_elem_l_2 = 0; i_p_elem_l_2 < K1_P_CB_SIZE_L_2; ++i_p_elem_l_2) {
                  K1_L_CB_RES_DEST(i_p_elem_l_1, i_p_elem_l_2) = 0;
                
                }
              }
            } // end of "i_p_cb_l_2"-loop
            #endif
            // post process whole extra cache blocks in dimension L_2
            #if K1_P_NUM_EXTRA_CB_L_2 > 0
            if (K1_L_FU_ID_L_2 < K1_P_NUM_EXTRA_CB_L_2) {  
              const size_t i_p_cb_l_2 = K1_P_NUM_CB_L_2;
              for (size_t i_p_elem_l_1 = 0; i_p_elem_l_1 < K1_P_CB_SIZE_L_1; ++i_p_elem_l_1) {
                for (size_t i_p_elem_l_2 = 0; i_p_elem_l_2 < K1_P_CB_SIZE_L_2; ++i_p_elem_l_2) {
                  K1_L_CB_RES_DEST(i_p_elem_l_1, i_p_elem_l_2) = 0;
                
                }
              }
            } // end of post processing whole extra cache blocks in dimension L_2
            #endif
            // post process single extra incomplete cache block in dimension L_2
            #if K1_P_NUM_EXTRA_ELEMS_L_2 > 0
            if (K1_L_FU_ID_L_2 == K1_P_NUM_EXTRA_CB_L_2 % K1_L_NUM_FU_L_2) {  
              const size_t i_p_cb_l_2 = K1_P_NUM_CB_L_2;
              for (size_t i_p_elem_l_1 = 0; i_p_elem_l_1 < K1_P_CB_SIZE_L_1; ++i_p_elem_l_1) {
                for (size_t i_p_elem_l_2 = 0; i_p_elem_l_2 < K1_P_CB_REDUCED_SIZE_IN_COMPLETE_L_CB_L_2; ++i_p_elem_l_2) {
                  K1_L_CB_RES_DEST(i_p_elem_l_1, i_p_elem_l_2) = 0;
                
                }
              }
            }// end of post process single extra incomplete cache block in dimension L_2
            #endif
          } // end of post processing whole extra cache blocks in dimension L_1
          #endif
          // post process single extra incomplete cache block in dimension L_1
          #if K1_P_NUM_EXTRA_ELEMS_L_1 > 0
          if (K1_L_FU_ID_L_1 == K1_P_NUM_EXTRA_CB_L_1 % K1_L_NUM_FU_L_1) {  
            const size_t i_p_cb_l_1 = K1_P_NUM_CB_L_1;
            #if K1_P_NUM_CB_L_2 > 0
            for (size_t i_p_cb_l_2 = 0; i_p_cb_l_2 < K1_P_NUM_CB_L_2; ++i_p_cb_l_2) {
              for (size_t i_p_elem_l_1 = 0; i_p_elem_l_1 < K1_P_CB_REDUCED_SIZE_IN_COMPLETE_L_CB_L_1; ++i_p_elem_l_1) {
                for (size_t i_p_elem_l_2 = 0; i_p_elem_l_2 < K1_P_CB_SIZE_L_2; ++i_p_elem_l_2) {
                  K1_L_CB_RES_DEST(i_p_elem_l_1, i_p_elem_l_2) = 0;
                
                }
              }
            } // end of "i_p_cb_l_2"-loop
            #endif
            // post process whole extra cache blocks in dimension L_2
