                  K1_P_CB_RES_DEST(i_p_elem_l_1, i_p_elem_l_2) += f(
                      K1_P_MEM_Z(i_p_elem_l_1, i_p_elem_l_2, i_p_elem_r_1),
                      K1_P_MEM_W(i_p_elem_l_1, i_p_elem_l_2, i_p_elem_r_1)
                  );
                
