                #if CACHE_L_CB != 0
                const size_t BUFFER_W_INDEX_2(i_p_elem_l_1, i_p_elem_l_2, i_p_elem_r_1) = index / (BUFFER_W_P_SIZE_1 * BUFFER_W_P_SIZE_0);
                const size_t BUFFER_W_INDEX_1(i_p_elem_l_1, i_p_elem_l_2, i_p_elem_r_1) = (index / (BUFFER_W_P_SIZE_0)) % BUFFER_W_P_SIZE_1;
                const size_t BUFFER_W_INDEX_0(i_p_elem_l_1, i_p_elem_l_2, i_p_elem_r_1) = index % BUFFER_W_P_SIZE_0;
                #else
                const size_t i_p_elem_l_1 = index / (K1_P_CB_SIZE_L_2 * K1_P_CB_REDUCED_SIZE_IN_COMPLETE_G_CB_R_1);
                const size_t i_p_elem_l_2 = (index / (K1_P_CB_REDUCED_SIZE_IN_COMPLETE_G_CB_R_1)) % K1_P_CB_SIZE_L_2;
                const size_t i_p_elem_r_1 = index % K1_P_CB_REDUCED_SIZE_IN_COMPLETE_G_CB_R_1;
                #endif
                K1_P_MEM_W(i_p_elem_l_1, i_p_elem_l_2, i_p_elem_r_1) = K1_L_MEM_W(K1_P_CB_OFFSET_L_1 + i_p_elem_l_1, K1_P_CB_OFFSET_L_2 + i_p_elem_l_2, K1_P_CB_OFFSET_R_1 + i_p_elem_r_1);
              }
              #endif
              #endif
              // ---------- end of P caching -------------
              
              for (size_t i_p_elem_l_1 = 0; i_p_elem_l_1 < K1_P_CB_SIZE_L_1; ++i_p_elem_l_1) {
                for (size_t i_p_elem_l_2 = 0; i_p_elem_l_2 < K1_P_CB_SIZE_L_2; ++i_p_elem_l_2) {
                  for (size_t i_p_elem_r_1 = 0; i_p_elem_r_1 < K1_P_CB_REDUCED_SIZE_IN_COMPLETE_G_CB_R_1; ++i_p_elem_r_1) {
                    // process one mda element
                    K1_P_CB_RES_DEST(i_p_elem_l_1, i_p_elem_l_2) += f(
                        K1_P_MEM_Z(i_p_elem_l_1, i_p_elem_l_2, i_p_elem_r_1),
                        K1_P_MEM_W(i_p_elem_l_1, i_p_elem_l_2, i_p_elem_r_1)
                    );
                  
                  }
                }
              }  
              #endif
            }// end of post process single extra incomplete cache block in dimension R_1
            #endif
            
            // ---------- reduction --------------------
            // will never be necessary on this level
            // because K1_P_NUM_FU_R == 1 for OpenCL
            // ---------- end of reduction -------------
            
            // move results upwards in memory hierarchy
            #if L_CB_RES_DEST_LEVEL > P_CB_RES_DEST_LEVEL || K1_P_NUM_FU_R_1 > 1
            #if K1_P_NUM_CB_IN_INCOMPLETE_L_CB_IN_COMPLETE_G_CB_R_1 == 0 && (K1_P_NUM_EXTRA_CB_IN_INCOMPLETE_L_CB_IN_COMPLETE_G_CB_R_1 + (K1_P_NUM_EXTRA_ELEMS_IN_INCOMPLETE_L_CB_IN_COMPLETE_G_CB_R_1 > 0)) < K1_L_NUM_FU_R_1
            if (K1_L_FU_ID_R_1 < (K1_P_NUM_EXTRA_CB_IN_INCOMPLETE_L_CB_IN_COMPLETE_G_CB_R_1 + (K1_P_NUM_EXTRA_ELEMS_IN_INCOMPLETE_L_CB_IN_COMPLETE_G_CB_R_1 > 0)))
            #endif
            {
              for (size_t i_p_elem_l_1 = 0; i_p_elem_l_1 < K1_P_CB_SIZE_L_1; ++i_p_elem_l_1) {
                for (size_t i_p_elem_l_2 = 0; i_p_elem_l_2 < K1_P_CB_SIZE_L_2; ++i_p_elem_l_2) {
                  K1_L_CB_RES_DEST(i_p_elem_l_1, i_p_elem_l_2) += K1_P_CB_RES_DEST(i_p_elem_l_1, i_p_elem_l_2);
                }
              }
            }
            #endif
          } // end of "i_p_cb_l_2"-loop
