                K1_P_MEM_W(i_p_elem_l_1, i_p_elem_l_2, i_p_elem_r_1) = K1_L_MEM_W(K1_P_CB_OFFSET_L_1 + i_p_elem_l_1, K1_P_CB_OFFSET_L_2 + i_p_elem_l_2, K1_P_CB_OFFSET_R_1 + i_p_elem_r_1);
              }
              #endif
              #if (K1_P_CB_SIZE_W / K1_P_CB_SIZE_L_1 * K1_P_CB_REDUCED_SIZE_IN_COMPLETE_L_CB_L_1 / K1_P_CB_SIZE_R_1 * K1_P_CB_REDUCED_SIZE_IN_COMPLETE_L_CB_R_1) % K1_P_FLAT_NUM_WI > 0
              if (K1_P_FLAT_WI_ID < (K1_P_CB_SIZE_W / K1_P_CB_SIZE_L_1 * K1_P_CB_REDUCED_SIZE_IN_COMPLETE_L_CB_L_1 / K1_P_CB_SIZE_R_1 * K1_P_CB_REDUCED_SIZE_IN_COMPLETE_L_CB_R_1) % K1_P_FLAT_NUM_WI) {
                const size_t index = K1_P_FLAT_WI_ID + ((K1_P_CB_SIZE_W / K1_P_CB_SIZE_L_1 * K1_P_CB_REDUCED_SIZE_IN_COMPLETE_L_CB_L_1 / K1_P_CB_SIZE_R_1 * K1_P_CB_REDUCED_SIZE_IN_COMPLETE_L_CB_R_1) / K1_P_FLAT_NUM_WI) * K1_P_FLAT_NUM_WI;
