            #if (K1_P_CB_SIZE_W / K1_P_CB_SIZE_L_1 * K1_P_CB_REDUCED_SIZE_IN_COMPLETE_L_CB_L_1 / K1_P_CB_SIZE_L_2 * K1_P_CB_REDUCED_SIZE_IN_COMPLETE_G_CB_L_2) % K1_P_FLAT_NUM_WI > 0
            if (K1_P_FLAT_WI_ID < (K1_P_CB_SIZE_W / K1_P_CB_SIZE_L_1 * K1_P_CB_REDUCED_SIZE_IN_COMPLETE_L_CB_L_1 / K1_P_CB_SIZE_L_2 * K1_P_CB_REDUCED_SIZE_IN_COMPLETE_G_CB_L_2) % K1_P_FLAT_NUM_WI) {
