              for (size_t step = 0; step < (K1_P_CB_SIZE_Z / K1_P_CB_SIZE_R_1 * K1_P_CB_REDUCED_SIZE_IN_COMPLETE_L_CB_R_1) / K1_P_FLAT_NUM_WI; ++step) {
