            #if K1_P_NUM_CB_R_1 > 0
            size_t i_p_cb_r_1 = 0;
            // ---------- P caching --------------------
            #if CACHE_P_CB != 0
            #if (K1_P_CB_SIZE_Z / K1_P_CB_SIZE_L_1 * K1_P_CB_REDUCED_SIZE_IN_COMPLETE_L_CB_L_1) / K1_P_FLAT_NUM_WI > 0
            for (size_t step = 0; step < (K1_P_CB_SIZE_Z / K1_P_CB_SIZE_L_1 * K1_P_CB_REDUCED_SIZE_IN_COMPLETE_L_CB_L_1) / K1_P_FLAT_NUM_WI; ++step) {
              const size_t index = K1_P_FLAT_WI_ID + step * K1_P_FLAT_NUM_WI;
