                const size_t i_p_elem_l_2 = (index / (K1_P_CB_REDUCED_SIZE_IN_COMPLETE_G_CB_R_1)) % K1_P_CB_REDUCED_SIZE_IN_COMPLETE_L_CB_L_2;
                const size_t i_p_elem_r_1 = index % K1_P_CB_REDUCED_SIZE_IN_COMPLETE_G_CB_R_1;
                #endif
