              }
              #endif
              #if (K1_P_CB_SIZE_W / K1_P_CB_SIZE_R_1 * K1_P_CB_REDUCED_SIZE_IN_COMPLETE_L_CB_R_1) % K1_P_FLAT_NUM_WI > 0
              if (K1_P_FLAT_WI_ID < (K1_P_CB_SIZE_W / K1_P_CB_SIZE_R_1 * K1_P_CB_REDUCED_SIZE_IN_COMPLETE_L_CB_R_1) % K1_P_FLAT_NUM_WI) {
                const size_t index = K1_P_FLAT_WI_ID + ((K1_P_CB_SIZE_W / K1_P_CB_SIZE_R_1 * K1_P_CB_REDUCED_SIZE_IN_COMPLETE_L_CB_R_1) / K1_P_FLAT_NUM_WI) * K1_P_FLAT_NUM_WI;
                #if CACHE_L_CB != 0
                const size_t BUFFER_W_INDEX_2(i_p_elem_l_1, i_p_elem_l_2, i_p_elem_r_1) = index / (BUFFER_W_P_SIZE_1 * BUFFER_W_P_SIZE_0);
                const size_t BUFFER_W_INDEX_1(i_p_elem_l_1, i_p_elem_l_2, i_p_elem_r_1) = (index / (BUFFER_W_P_SIZE_0)) % BUFFER_W_P_SIZE_1;
                const size_t BUFFER_W_INDEX_0(i_p_elem_l_1, i_p_elem_l_2, i_p_elem_r_1) = index % BUFFER_W_P_SIZE_0;
                #else
