                for (size_t i_p_elem_l_2 = 0; i_p_elem_l_2 < K1_P_CB_SIZE_L_2; ++i_p_elem_l_2) {
                  for (size_t i_p_elem_r_1 = 0; i_p_elem_r_1 < K1_P_CB_REDUCED_SIZE_IN_COMPLETE_L_CB_R_1; ++i_p_elem_r_1) {
