              #if CACHE_L_CB != 0
              const size_t BUFFER_Z_INDEX_1(i_p_elem_l_1, i_p_elem_r_1) = index / (BUFFER_Z_P_SIZE_0);
              const size_t BUFFER_Z_INDEX_0(i_p_elem_l_1, i_p_elem_r_1) = index % BUFFER_Z_P_SIZE_0;
