            for (i_p_cb_r_1 = 1; i_p_cb_r_1 < K1_P_NUM_CB_IN_INCOMPLETE_L_CB_IN_COMPLETE_G_CB_R_1; ++i_p_cb_r_1) {
              // ---------- P caching --------------------
              #if CACHE_P_CB != 0
              #if K1_P_CB_SIZE_Z / K1_P_FLAT_NUM_WI > 0
              for (size_t step = 0; step < K1_P_CB_SIZE_Z / K1_P_FLAT_NUM_WI; ++step) {
