                K1_P_MEM_Z(i_p_elem_l_1, 0, i_p_elem_r_1) = K1_L_MEM_Z(K1_P_CB_OFFSET_L_1 + i_p_elem_l_1, K1_P_CB_OFFSET_L_2 + 0, K1_P_CB_OFFSET_R_1 + i_p_elem_r_1);
              }
              #endif
              #if (K1_P_CB_SIZE_Z / K1_P_CB_SIZE_R_1 * K1_P_CB_REDUCED_SIZE_IN_COMPLETE_L_CB_R_1) % K1_P_FLAT_NUM_WI > 0
              if (K1_P_FLAT_WI_ID < (K1_P_CB_SIZE_Z / K1_P_CB_SIZE_R_1 * K1_P_CB_REDUCED_SIZE_IN_COMPLETE_L_CB_R_1) % K1_P_FLAT_NUM_WI) {
                const size_t index = K1_P_FLAT_WI_ID + ((K1_P_CB_SIZE_Z / K1_P_CB_SIZE_R_1 * K1_P_CB_REDUCED_SIZE_IN_COMPLETE_L_CB_R_1) / K1_P_FLAT_NUM_WI) * K1_P_FLAT_NUM_WI;
                #if CACHE_L_CB != 0
                const size_t BUFFER_Z_INDEX_1(i_p_elem_l_1, i_p_elem_r_1) = index / (BUFFER_Z_P_SIZE_0);
                const size_t BUFFER_Z_INDEX_0(i_p_elem_l_1, i_p_elem_r_1) = index % BUFFER_Z_P_SIZE_0;
                #else
                const size_t i_p_elem_l_1 = index / (K1_P_CB_REDUCED_SIZE_IN_COMPLETE_L_CB_R_1);
                const size_t i_p_elem_r_1 = index % K1_P_CB_REDUCED_SIZE_IN_COMPLETE_L_CB_R_1;
