              // ---------- P caching --------------------
              #if CACHE_P_CB != 0
              #if (K1_P_CB_SIZE_Z / K1_P_CB_SIZE_L_1 * K1_P_CB_REDUCED_SIZE_IN_COMPLETE_G_CB_L_1) / K1_P_FLAT_NUM_WI > 0
              for (size_t step = 0; step < (K1_P_CB_SIZE_Z / K1_P_CB_SIZE_L_1 * K1_P_CB_REDUCED_SIZE_IN_COMPLETE_G_CB_L_1) / K1_P_FLAT_NUM_WI; ++step) {
