              #if L_CB_RES_DEST_LEVEL > P_CB_RES_DEST_LEVEL
              for (size_t i_p_elem_l_1 = 0; i_p_elem_l_1 < K1_P_CB_REDUCED_SIZE_IN_COMPLETE_G_CB_L_1; ++i_p_elem_l_1) {
                for (size_t i_p_elem_l_2 = 0; i_p_elem_l_2 < K1_P_CB_SIZE_L_2; ++i_p_elem_l_2) {
                  size_t i_p_elem_r_1 = 0;
                  // process one mda element
                  K1_P_CB_RES_DEST(i_p_elem_l_1, i_p_elem_l_2) = f(
                      K1_P_MEM_Z(i_p_elem_l_1, i_p_elem_l_2, i_p_elem_r_1),
                      K1_P_MEM_W(i_p_elem_l_1, i_p_elem_l_2, i_p_elem_r_1)
                  );
                  
                  #if K1_P_CB_REDUCED_SIZE_IN_COMPLETE_L_CB_R_1 > 1
                  for (i_p_elem_r_1 = 1; i_p_elem_r_1 < K1_P_CB_REDUCED_SIZE_IN_COMPLETE_L_CB_R_1; ++i_p_elem_r_1) {
                    // process one mda element
                    K1_P_CB_RES_DEST(i_p_elem_l_1, i_p_elem_l_2) += f(
                        K1_P_MEM_Z(i_p_elem_l_1, i_p_elem_l_2, i_p_elem_r_1),
                        K1_P_MEM_W(i_p_elem_l_1, i_p_elem_l_2, i_p_elem_r_1)
                    );
                  
                  }
                  #endif
                
                }
              }
              #else
              for (size_t i_p_elem_l_1 = 0; i_p_elem_l_1 < K1_P_CB_REDUCED_SIZE_IN_COMPLETE_G_CB_L_1; ++i_p_elem_l_1) {
                for (size_t i_p_elem_l_2 = 0; i_p_elem_l_2 < K1_P_CB_SIZE_L_2; ++i_p_elem_l_2) {
                  for (size_t i_p_elem_r_1 = 0; i_p_elem_r_1 < K1_P_CB_REDUCED_SIZE_IN_COMPLETE_L_CB_R_1; ++i_p_elem_r_1) {
                    // process one mda element
                    K1_P_CB_RES_DEST(i_p_elem_l_1, i_p_elem_l_2) += f(
                        K1_P_MEM_Z(i_p_elem_l_1, i_p_elem_l_2, i_p_elem_r_1),
                        K1_P_MEM_W(i_p_elem_l_1, i_p_elem_l_2, i_p_elem_r_1)
                    );
                  
                  }
                }
              }
              #endif  
              #else
              // ---------- P caching --------------------
              #if CACHE_P_CB != 0
              #if (K1_P_CB_SIZE_Z / K1_P_CB_SIZE_L_1 * K1_P_CB_REDUCED_SIZE_IN_COMPLETE_G_CB_L_1 / K1_P_CB_SIZE_R_1 * K1_P_CB_REDUCED_SIZE_IN_COMPLETE_L_CB_R_1) / K1_P_FLAT_NUM_WI > 0
              for (size_t step = 0; step < (K1_P_CB_SIZE_Z / K1_P_CB_SIZE_L_1 * K1_P_CB_REDUCED_SIZE_IN_COMPLETE_G_CB_L_1 / K1_P_CB_SIZE_R_1 * K1_P_CB_REDUCED_SIZE_IN_COMPLETE_L_CB_R_1) / K1_P_FLAT_NUM_WI; ++step) {
