            if (K1_P_FLAT_WI_ID < (K1_P_CB_SIZE_W / K1_P_CB_SIZE_L_2 * K1_P_CB_REDUCED_SIZE_IN_COMPLETE_G_CB_L_2) % K1_P_FLAT_NUM_WI) {
              const size_t index = K1_P_FLAT_WI_ID + ((K1_P_CB_SIZE_W / K1_P_CB_SIZE_L_2 * K1_P_CB_REDUCED_SIZE_IN_COMPLETE_G_CB_L_2) / K1_P_FLAT_NUM_WI) * K1_P_FLAT_NUM_WI;
              #if CACHE_L_CB != 0
